      "name": "lp.norm_neg",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "theorem",
      "type": "∀ {α : Type u_3} {E : α → Type u_4} {p : ENNReal} [inst : (i : α) → NormedAddCommGroup (E i)] ⦃f : ↥(lp E p)⦄,\n  ‖-f‖ = ‖f‖"
    },
    {
      "name": "PadicSeq.norm_neg",
      "module_name": "Mathlib.NumberTheory.Padics.PadicNumbers",
      "kind": "theorem",
      "type": "∀ {p : ℕ} [hp : Fact (Nat.Prime p)] (a : PadicSeq p), (-a).norm = a.norm"
    },
    {
      "name": "nnnorm_neg",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {E : Type u_5} [inst : SeminormedAddGroup E] (a : E), ‖-a‖₊ = ‖a‖₊"
    },
    {
      "name": "MeasureTheory.Lp.norm_neg",
      "module_name": "Mathlib.MeasureTheory.Function.LpSpace.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_4} {m : MeasurableSpace α} {p : ENNReal} {μ : MeasureTheory.Measure α}\n  [inst : NormedAddCommGroup E] (f : ↥(MeasureTheory.Lp E p μ)), ‖-f‖ = ‖f‖"
    },
    {
      "name": "Zsqrtd.norm_neg",
      "module_name": "Mathlib.NumberTheory.Zsqrtd.Basic",
      "kind": "theorem",
      "type": "∀ {d : ℤ} (x : ℤ√d), (-x).norm = x.norm"
    },
    {
      "name": "ContinuousLinearMap.opNorm_neg",
      "module_name": "Mathlib.Analysis.Normed.Operator.Basic",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u_1} {𝕜₂ : Type u_2} {E : Type u_4} {F : Type u_5} [inst : SeminormedAddCommGroup E]\n  [inst_1 : SeminormedAddCommGroup F] [inst_2 : NontriviallyNormedField 𝕜] [inst_3 : NontriviallyNormedField 𝕜₂]\n  [inst_4 : NormedSpace 𝕜 E] [inst_5 : NormedSpace 𝕜₂ F] {σ₁₂ : 𝕜 →+* 𝕜₂} (f : E →SL[σ₁₂] F), ‖-f‖ = ‖f‖"
    }
  ]
